"""Kiểm khuôn kịch bản chi tiết EAT IN THE KITCHEN (văn bản thuần, khuôn của 02).

Dùng: python -X utf8 kiem_kich_ban.py <file.txt> [--cum-dau N --cum-cuoi M]
In ra lỗi (LOI) và cảnh báo (CANH BAO) theo từng cụm.
"""
import re
import sys

RE_CUM = re.compile(r"^CỤM (\d+) — ")
RE_TAP = re.compile(r"^TẬP (\d+) — ")
RE_SHOT = re.compile(r"^\[\s*(\d+)–\s*(\d+)\s*s\]")
RE_THOAI = re.compile(r"^ {10}([A-ZÀ-Ỹ][A-ZÀ-Ỹ .'’\-]+?): (.*)$")


def kiem(duong_dan, cum_dau=1, cum_cuoi=70):
    with open(duong_dan, encoding="utf-8") as f:
        dong = f.read().splitlines()

    loi, canh_bao = [], []
    cac_cum, cac_tap = [], []
    hien_tai = None

    def dong_cum():
        if hien_tai is None:
            return
        n = hien_tai["so"]
        shots = hien_tai["shots"]
        if not shots:
            loi.append(f"C{n}: không có shot")
            return
        if shots[0][0] != 0:
            loi.append(f"C{n}: shot đầu không bắt đầu ở 0s")
        for (a1, b1, _), (a2, b2, _) in zip(shots, shots[1:]):
            if a2 != b1:
                loi.append(f"C{n}: mốc giây không liền ({a1}–{b1} rồi {a2}–{b2})")
        if shots[-1][1] != 30:
            loi.append(f"C{n}: shot cuối kết ở {shots[-1][1]}s, không phải 30s")
        if not 7 <= len(shots) <= 10:
            canh_bao.append(f"C{n}: {len(shots)} shot (chuẩn 7–10)")
        for a, b, so_thoai in shots:
            if b - a > 5:
                canh_bao.append(f"C{n}: shot {a}–{b}s dài {b - a}s")
            if b - a < 1:
                loi.append(f"C{n}: shot {a}–{b}s dài < 1s")
            if so_thoai > 1:
                canh_bao.append(f"C{n}: shot {a}–{b}s có {so_thoai} câu thoại")
        if shots[-1][2]:
            loi.append(f"C{n}: shot cuối có thoại")
        if len(hien_tai["thoai"]) > 6:
            canh_bao.append(f"C{n}: {len(hien_tai['thoai'])} câu thoại (tối đa 6)")
        if not hien_tai["ket"]:
            loi.append(f"C{n}: thiếu KẾT")
        if not hien_tai["moc"]:
            loi.append(f"C{n}: thiếu MÓC")
        for k in ("nhan_vat", "tinh_than"):
            if not hien_tai[k]:
                loi.append(f"C{n}: thiếu dòng {k}")
        cac_cum.append(hien_tai)

    for i, d in enumerate(dong, 1):
        if len(d) > 120:
            canh_bao.append(f"dòng {i}: dài {len(d)} ký tự")
        m = RE_TAP.match(d)
        if m:
            cac_tap.append((int(m.group(1)), i))
            continue
        m = RE_CUM.match(d)
        if m:
            dong_cum()
            hien_tai = {"so": int(m.group(1)), "dong": i, "shots": [], "thoai": [],
                        "ket": False, "moc": False, "nhan_vat": False, "tinh_than": False}
            continue
        if hien_tai is None:
            continue
        if d.startswith("Nhân vật:"):
            hien_tai["nhan_vat"] = True
        elif d.startswith("Tinh thần:"):
            hien_tai["tinh_than"] = True
        elif d.startswith("KẾT:"):
            hien_tai["ket"] = True
        elif d.startswith("MÓC:"):
            hien_tai["moc"] = True
        m = RE_SHOT.match(d)
        if m:
            hien_tai["shots"].append([int(m.group(1)), int(m.group(2)), 0])
            continue
        m = RE_THOAI.match(d)
        if m:
            ten, cau = m.group(1), m.group(2)
            hien_tai["thoai"].append((ten, cau))
            if hien_tai["shots"]:
                hien_tai["shots"][-1][2] += 1
            else:
                loi.append(f"C{hien_tai['so']}: thoại trước shot đầu (dòng {i})")
            khong_ascii = sorted({c for c in cau if ord(c) > 126})
            if khong_ascii:
                loi.append(f"C{hien_tai['so']}: thoại có ký tự ngoài ASCII {khong_ascii}: {cau}")
            so_tu = len(cau.split())
            if so_tu > 12:
                loi.append(f"C{hien_tai['so']}: câu {so_tu} từ: {ten}: {cau}")
            elif so_tu > 10:
                canh_bao.append(f"C{hien_tai['so']}: câu {so_tu} từ: {ten}: {cau}")
    dong_cum()

    so_cum = [c["so"] for c in cac_cum]
    mong_doi = list(range(cum_dau, cum_cuoi + 1))
    if so_cum != mong_doi:
        thieu = sorted(set(mong_doi) - set(so_cum))
        thua = sorted(set(so_cum) - set(mong_doi))
        lap = sorted({x for x in so_cum if so_cum.count(x) > 1})
        loi.append(f"Thứ tự cụm sai. Thiếu {thieu}, thừa {thua}, lặp {lap}")

    so_thoai = sum(len(c["thoai"]) for c in cac_cum)
    print(f"Cụm: {len(cac_cum)} · Tập: {[t for t, _ in cac_tap]} · Câu thoại: {so_thoai}")
    for x in loi:
        print("LOI      ", x)
    for x in canh_bao:
        print("CANH BAO ", x)
    print(f"Tổng: {len(loi)} lỗi, {len(canh_bao)} cảnh báo")
    return cac_cum


if __name__ == "__main__":
    args = sys.argv[1:]
    dau, cuoi = 1, 70
    if "--cum-dau" in args:
        dau = int(args[args.index("--cum-dau") + 1])
    if "--cum-cuoi" in args:
        cuoi = int(args[args.index("--cum-cuoi") + 1])
    kiem(args[0], dau, cuoi)

content.text:
Mình đã soát lại kịch bản ở mức truyện: thoại, móc cuối cụm, nhịp lên xuống của 70 cụm. Kết luận: kịch bản đã đủ cuốn và kịch tính, nên mình đã chốt và điền vào [04_kich-ban-chinh-thuc.md](04_kich-ban-chinh-thuc.md).

**Vì sao mình đánh giá là đã đạt:**
- **Mở phim:** giây đầu là cú giật túi. Đến phút 1:30 đã có câu "Your plate's in the kitchen.", phút thứ 3 bà nói "I understood every word.".
- **Lật mặt dày và tăng dần:** cứ 2–4 phút có một lần lật mặt, kẻ nhỏ trước, kẻ lớn sau:
  - phút 3: Charlene không trả lời nổi câu tiếng Pháp;
  - phút 8: bỏ chạy ở tiệm tạp hoá;
  - phút 12: phòng họp;
  - phút 14: "He's my son";
  - phút 18: nhà hàng;
  - phút 20: "Welcome home";
  - phút 23: Devin mất việc;
  - phút 27: bệnh án giả;
  - phút 30: còng tay ngay trên livestream của chính Raven.
- **Móc:** cụm nào cũng kết bằng một câu hỏi rõ ràng và được trả ngay trong 1–2 cụm sau. Không có đoạn nào bình yên quá 1 phút.
- **Phản diện bị ghét ngay câu đầu**, và trả giá đủ ba tầng: mất tiền và nhà, bị còng tay, bị chính bạn nhà thờ nói lại câu "Serve the gumbo".
- **Bà tự thắng bằng tài của mình** (phiên dịch không cần giấy, tự vạch trần bệnh án giả), không ngồi chờ người khác cứu.
- **Devin lật mặt có lý do rõ:** anh nghe Raven định bỏ mình, và chính mẹ đặt lựa chọn vào tay anh. Cảnh kết trả đúng tên phim: bà kéo ghế ở bàn ăn cho con.

**Chỗ duy nhất mình sửa:** ở cụm 20, bà nói với Devin "Find yourself another translator". Vậy mà sang cụm 26 bà nhận lời tới cứu công ty của anh, khán giả dễ thắc mắc vì sao. Giờ bà trả lời Inès: "For you, Ines. Twenty minutes." Như vậy bà vẫn giữ đúng lời đã nói với con, và cảnh "He's my son" ngay sau đó càng nặng hơn.

**File 04 bây giờ:**
- Giữ phần đầu mẫu, điền ngày chốt 02/11/2026.
- Thêm một dòng khuôn phim và một dòng nguồn.
- Bên dưới là toàn bộ kịch bản 70 cụm, khớp từng chữ với phần kịch bản trong file 03.
- Kiểm tự động 0 lỗi.

Mình chưa commit và chưa chạy `CHOT-MOC.bat`, vì bước đó ký số và đóng dấu thời gian cho bản chính thức, nên để bạn tự bấm khi đã đọc xong.

