file.content:
# -*- coding: utf-8 -*-
"""Dựng bible.json + du_an.json + anh/_ten_anh.json cho DIRT ON HER HANDS từ kịch bản chốt (04_kich-ban-chinh-thuc.md).
Chọn refs của từng cụm theo luật: panel bối cảnh TRƯỚC, ảnh nhân vật, ảnh đạo cụ SAU; tối đa 9 ảnh.
Dùng: python -X utf8 build_du_an.py"""
import json, re
from pathlib import Path

DUAN = Path(r"F:\Tungnd\phim\DIRT_ON_HER_HANDS")
KB = Path(r"F:\Tungnd\Github\dirt-on-her-hands\04_kich-ban-chinh-thuc.md")

# ---------------- bảng 4 góc ----------------
BOARDS = {
    "KHO_BANG": ["KHO_STAGE", "KHO_BAR", "KHO_DOOR", "KHO_JARS"],
    "YARD_NIGHT_BANG": ["YARD_FACADE", "YARD_LOT", "YARD_TRUCK", "YARD_ROAD"],
    "YARD_DAY_BANG": ["YARDD_FACADE", "YARDD_LOT", "YARDD_TRUCK", "YARDD_ROAD"],
    "BUS_BANG": ["BUS_FRONT", "BUS_RIGHT", "BUS_REAR", "BUS_LEFT"],
    "ROAD_BANG": ["ROAD_ALONG", "ROAD_TREES", "ROAD_BACK", "ROAD_FIELD"],
    "PORCH_BANG": ["PORCH_SWING", "PORCH_ORCHARD", "PORCH_STEPS", "PORCH_END"],
}
PROPS = ["ICE_BUCKET", "GIFT_GOLD", "WHITE_BOX_BOWL", "RING", "PEN_REMOTE", "INVOICES", "POA_PAPERS", "CLIPBOARD", "REVOCATION",
         "DEED", "SONOGRAM", "POLICE_REPORT", "FLIP_PHONE", "BUTTER_DISH", "COMPANY_CARD", "COACH", "PICKUP"]

# ---------------- nhân vật ----------------
TEN = {"WILLA": "WILLA", "DANIELLE": "DANIELLE", "DERRICK": "DERRICK", "TARYN": "TARYN", "LUCIUS": "LUCIUS", "ODELL": "ODELL",
       "RUTH": "RUTH", "ANIYAH": "ANIYAH", "LONNIE": "LONNIE", "BÁC SĨ PRUITT": "PRUITT", "PRUITT": "PRUITT", "RENEE": "RENEE",
       "CALLOWAY": "CALLOWAY", "LORETTA": "LORETTA", "BẢO VỆ": "GUARD", "PHÓ CẢNH SÁT TRƯỞNG": "DEPUTY", "BÉ GÁI": "MAE"}
SHEET = {"LUCIUS": "SHEET_LUCIUS_L1", "ODELL": "SHEET_ODELL_O1", "RUTH": "SHEET_RUTH_R1", "ANIYAH": "SHEET_ANIYAH_A1",
         "LONNIE": "SHEET_LONNIE_LN1", "PRUITT": "SHEET_PRUITT_P1", "RENEE": "SHEET_RENEE_RN1", "CALLOWAY": "SHEET_CALLOWAY_C1",
         "LORETTA": "SHEET_LORETTA_LO1", "GUARD": "SHEET_GUARD_G1", "DEPUTY": "SHEET_DEPUTY_D1", "MAE": "SHEET_MAE_M1"}


def sheet_cua(ten, n):
    if ten == "WILLA":
        return "SHEET_WILLA_W2" if n >= 68 else ("SHEET_WILLA_W1" if 35 <= n <= 48 else "SHEET_WILLA_W1M")
    if ten == "DANIELLE":
        return "SHEET_DANIELLE_DA2" if n >= 68 else "SHEET_DANIELLE_DA1"
    if ten == "DERRICK":
        return "SHEET_DERRICK_DE2" if n >= 69 else "SHEET_DERRICK_DE1"
    if ten == "TARYN":
        return "SHEET_TARYN_T1" if 35 <= n <= 48 else "SHEET_TARYN_T2"
    return SHEET[ten]


# ---------------- bối cảnh từng cụm ----------------
def boards_cua(n):
    if n in (4,):
        return ["KHO_BANG", "YARD_NIGHT_BANG"]
    if n == 17 or n == 67:
        return ["YARD_NIGHT_BANG"]
    if n == 18:
        return ["KHO_BANG", "YARD_NIGHT_BANG"]
    if n == 35 or 36 <= n <= 47:
        return ["BUS_BANG"]
    if n in (44, 45):
        return ["BUS_BANG", "YARD_DAY_BANG"]
    if n == 48:
        return ["BUS_BANG", "ROAD_BANG"]
    if n == 49:
        return ["ROAD_BANG", "YARD_DAY_BANG"]
    if n >= 68:
        return ["PORCH_BANG"]
    return ["KHO_BANG"]


PANEL_MAC_DINH = {
    ("YARD_NIGHT_BANG", 4): ["YARD_FACADE", "YARD_LOT"], ("YARD_NIGHT_BANG", 17): ["YARD_FACADE", "YARD_LOT"],
    ("YARD_NIGHT_BANG", 18): ["YARD_FACADE", "YARD_LOT"], ("YARD_NIGHT_BANG", 67): ["YARD_LOT", "YARD_TRUCK", "YARD_ROAD"],
    ("YARD_DAY_BANG", 44): ["YARDD_FACADE", "YARDD_LOT"], ("YARD_DAY_BANG", 45): ["YARDD_FACADE", "YARDD_LOT"],
    ("YARD_DAY_BANG", 49): ["YARDD_FACADE"],
    ("ROAD_BANG", 48): ["ROAD_ALONG", "ROAD_TREES"], ("ROAD_BANG", 49): ["ROAD_ALONG", "ROAD_TREES"],
    ("PORCH_BANG", 68): ["PORCH_SWING", "PORCH_STEPS", "PORCH_ORCHARD"], ("PORCH_BANG", 69): ["PORCH_STEPS", "PORCH_SWING"],
    ("PORCH_BANG", 70): ["PORCH_STEPS", "PORCH_ORCHARD", "PORCH_SWING"],
}


def panel_kho(text):
    s = []
    cam = " ".join(re.findall(r"Máy [^:]*:", text))
    if re.search(r"bục|bàn gia đình|ghế chủ toạ|màn chiếu", cam): s.append("KHO_STAGE")
    if re.search(r"cửa kho|cửa trượt", cam): s.append("KHO_DOOR")
    if re.search(r"bàn nông dân|dãy bàn", cam): s += ["KHO_BAR", "KHO_JARS"]
    if re.search(r"cửa hông|quầy gỗ", cam): s.append("KHO_BAR")
    return s


def panel_bus(text):
    s = []
    cam = " ".join(re.findall(r"(?:Máy|Góc cao)[^:]*:", text))
    if re.search(r"cuối xe|mắt camera|dọc lối đi", cam): s.append("BUS_REAR")
    if re.search(r"đầu xe|ghế tài xế|kính chắn gió", cam): s.append("BUS_FRONT")
    if re.search(r"bên phải|ghế cửa sổ 3A|ghế 3A", cam): s.append("BUS_RIGHT")
    if re.search(r"bên trái", cam): s.append("BUS_LEFT")
    return s


def panels_cua(n, board, shots_text):
    if (board, n) in PANEL_MAC_DINH:
        return PANEL_MAC_DINH[(board, n)]
    thu = []
    if board == "KHO_BANG":
        thu = panel_kho(shots_text) or ["KHO_STAGE", "KHO_DOOR"]
    elif board == "BUS_BANG":
        thu = panel_bus(shots_text) or ["BUS_REAR", "BUS_RIGHT"]
        thu = thu if len(thu) >= 2 else (thu + ["BUS_REAR", "BUS_FRONT", "BUS_RIGHT"])[:2]
    seen = []
    for p in thu:
        if p not in seen: seen.append(p)
    return seen


PROP_LUAT = [  # (prop, mẫu tìm trong CẢ cụm, chỉ khi cụm nằm trong danh sách nếu có)
    ("COACH", r"xe khách ĐỖ ở lề|bước xuống bậc cửa xe|bóng xe khách|xe khách lăn bánh", {48}),
    ("PICKUP", r"bán tải", {49, 67}),
    ("FLIP_PHONE", r"điện thoại nắp gập", {45, 46, 47}),
    ("COMPANY_CARD", r"thẻ công ty|tấm thẻ mang tên", {39}),
    ("WHITE_BOX_BOWL", r"hộp quà trắng|bát pha lê", {36, 37}),
    ("PEN_REMOTE", r"bút bạc|điều khiển nhỏ", {27, 34}),
    ("INVOICES", r"hoá đơn|hồ sơ", {14, 15, 16}),
    ("POA_PAPERS", r"xấp giấy gấp ba|bìa xanh", {17, 31}),
    ("CLIPBOARD", r"bìa kẹp giấy xanh", {32}),
    ("REVOCATION", r"tập giấy kẹp ghim", {55}),
    ("DEED", r"khế ước", {59, 60}),
    ("SONOGRAM", r"phiếu siêu âm", {61, 66}),
    ("POLICE_REPORT", r"giấy báo mất nhẫn", {52, 53}),
    ("BUTTER_DISH", r"bơ", {64}),
    ("GIFT_GOLD", r"hộp quà vàng|quà bọc giấy vàng", {1, 5, 7, 8}),
    ("ICE_BUCKET", r"xô đá", {1, 2, 3, 53, 66}),
    ("RING", r"INSERT[^\n]*nhẫn|nhẫn kim cương cổ[^\n]*lấp lánh", {2, 5, 64}),
]


def parse(kb):
    L = kb.read_text(encoding="utf-8").split("\n")
    cl, cur = [], None
    for ln in L:
        m = re.match(r"^CỤM (\d+) — (.*)$", ln)
        if m:
            cur = {"n": int(m.group(1)), "title": m.group(2), "head": [], "shots": [], "ket": [], "moc": "", "raw": [ln]}
            cl.append(cur); mode = "head"; continue
        if cur is None: continue
        if re.match(r"^-{50,}$", ln): cur["raw"].append(ln); cur = None; continue
        cur["raw"].append(ln)
        if ln.startswith("KẾT:"): mode = "ket"; cur["ket"].append(ln[4:].strip()); continue
        if ln.startswith("MÓC:"): cur["moc"] = ln[4:].strip(); mode = "moc"; continue
        s = re.match(r"^\[\s*(\d+)–(\d+)\s?s\]\s+(.+?)\s+—\s+(.*)$", ln)
        if s:
            mode = "shot"
            cur["shots"].append({"a": int(s.group(1)), "b": int(s.group(2)), "co": s.group(3), "hinh": s.group(4), "noi": "", "thoai": ""})
            continue
        d = re.match(r"^ {10}([A-ZÀ-Ỵ][A-ZÀ-Ỵ ]*?): (.*)$", ln)
        if d and mode == "shot":
            cur["shots"][-1]["noi"] = TEN.get(d.group(1), d.group(1)); cur["shots"][-1]["thoai"] = d.group(2).strip(); continue
        if mode == "head": cur["head"].append(ln)
        elif mode == "shot" and ln.strip(): cur["shots"][-1]["hinh"] += " " + ln.strip()
        elif mode == "ket" and ln.strip(): cur["ket"].append(ln.strip())
    return cl


def main():
    cl = parse(KB)
    assert [c["n"] for c in cl] == list(range(1, 71)), [c["n"] for c in cl][:5]
    bible_cl, du_cum, tm_nv = [], [], {}
    for c in cl:
        n = c["n"]
        head = c["head"]
        loc = head[0] if head else ""
        cast_line = next((x for x in head if x.startswith("Nhân vật:")), "")
        cast = []
        for t in re.split(r"\s*·\s*", cast_line.replace("Nhân vật:", "").strip()):
            t = re.sub(r"\(.*?\)", "", t).strip()
            if t in TEN and TEN[t] not in cast: cast.append(TEN[t])
        shots_text = " ".join(s["hinh"] for s in c["shots"]) + " " + " ".join(c["ket"])
        # người xuất hiện trong thoại nhưng không có trong dòng Nhân vật
        for s in c["shots"]:
            if s["noi"] and s["noi"] in SHEET.values() or s["noi"] in ("WILLA", "DANIELLE", "DERRICK", "TARYN"):
                if s["noi"] not in cast: cast.append(s["noi"])
        boards = boards_cua(n)
        panels = []
        for b in boards:
            panels += panels_cua(n, b, shots_text)
        cap_panel = 4 if len(cast) <= 3 else (3 if len(cast) <= 4 else 2)
        full_text = shots_text + " " + " ".join(f"INSERT {s['hinh']}" if s["co"].lower().startswith("chèn") else "" for s in c["shots"])
        props = []
        for p, pat, ds in PROP_LUAT:
            if n in ds and re.search(pat, full_text) and p not in props: props.append(p)
        props = props[:2]
        if len(boards) == 1: panels = panels[:cap_panel]
        else: panels = panels[:max(cap_panel, 2) + (1 if len(cast) <= 3 else 0)]
        noi_ds = []
        for s in c["shots"]:
            if s["noi"] and s["noi"] not in noi_ds: noi_ds.append(s["noi"])
        ca = [t for t in noi_ds if t in cast] + [t for t in cast if t not in noi_ds]    # người nói trước, rồi người im lặng
        while len(ca) + len(panels) + len(props) > 9:
            if props: props.pop()
            elif len(panels) > 2: panels.pop()
            elif [t for t in ca if t not in noi_ds]: ca.remove([t for t in ca if t not in noi_ds][-1])
            elif len(panels) > 1: panels.pop()
            else: ca.pop()
        ten_cast = ca
        refs = panels + [sheet_cua(t, n) for t in ten_cast] + ["PROP_" + p for p in props]
        refs = refs[:9]
        bible_cl.append({"n": n, "title": c["title"], "loc": loc, "cast": cast, "cast_gui": ten_cast, "bo_khung": ["DAU", "GIUA", "CUOI"],
                         "shots": [{"t": f"{s['a']}-{s['b']}", "a": s["a"], "b": s["b"], "co": s["co"], "hinh": s["hinh"],
                                    "noi": s["noi"], "thoai": s["thoai"]} for s in c["shots"]],
                         "refs": refs, "boards": boards, "end_state": " ".join(c["ket"]), "moc": c["moc"]})
        du_cum.append({"n": n, "boi_canh": boards[0], "am_thanh": "", "tinh_than": " ".join(x.strip() for x in head if x.startswith("Tinh")),
                       "bat_dau": c["shots"][0]["hinh"][:300], "ket_thuc": " ".join(c["ket"]), "truoc_do": "", "do": {},
                       "shots": [{"a": float(s["a"]), "b": float(s["b"]), "co": s["co"].upper(), "ai": "", "hinh": "" if s["thoai"] else s["hinh"],
                                  "noi": s["noi"], "thoai": s["thoai"]} for s in c["shots"]], "refs": refs})
    # tên ảnh
    tm = json.loads((DUAN / "anh" / "_ten_anh.json").read_text(encoding="utf-8"))
    for b, ps in BOARDS.items():
        tm[b] = {"loai": "boi_canh", "ten": b}
        for p in ps: tm[p] = {"loai": "boi_canh", "ten": p}
    for p in PROPS: tm["PROP_" + p] = {"loai": "dao_cu", "ten": "PROP_" + p}
    tm["SHEET_WILLA_W1"] = {"loai": "nv", "ten": "WILLA"}
    (DUAN / "anh" / "_ten_anh.json").write_text(json.dumps(tm, ensure_ascii=False, indent=1), encoding="utf-8")
    chars = sorted({t for c in bible_cl for t in c["cast"]})
    bible = {"meta": {"name": "DIRT ON HER HANDS"}, "characters": [{"name": t} for t in chars], "clusters": bible_cl}
    (DUAN / "bible.json").write_text(json.dumps(bible, ensure_ascii=False, indent=1), encoding="utf-8")
    du = {"ten": "DIRT ON HER HANDS", "phong_cach": "", "ti_le_video": "16:9",
          "nhan_vat": {t: {"tuoi": "", "mo_ta": "", "giong": "", "do": {}} for t in chars},
          "boi_canh": {b: {"mo_ta": b, "anh_sang": ""} for b in BOARDS}, "dao_cu": {"PROP_" + p: {"mo_ta": p, "anh_sang": ""} for p in PROPS},
          "bang_4_goc": {b: {"boi_canh": [], "panels": ps} for b, ps in BOARDS.items()}, "cum": du_cum}
    (DUAN / "du_an.json").write_text(json.dumps(du, ensure_ascii=False, indent=1), encoding="utf-8")
    # thống kê
    print("cụm:", len(bible_cl), "| ảnh/cụm tối đa:", max(len(c["refs"]) for c in bible_cl))
    for c in bible_cl:
        if len(c["cast"]) > len(c["cast_gui"]):
            print(f"  cụm {c['n']}: cast {len(c['cast'])} nhưng chỉ gửi ảnh {len(c['cast_gui'])} -> bỏ {[t for t in c['cast'] if t not in c['cast_gui']]}")


if __name__ == "__main__":
