def kiem(n, cl, refs, tm, txt, cu="", ten_phim=()):
    loi, cb = [], []
    txt = txt.replace("\r\n", "\n")
    if txt.startswith("﻿"):
        loi.append("file có BOM")
    if not txt.startswith("参考图识别说明"):
        loi.append("phải mở bằng 参考图识别说明…")
    for x in ("【场景图】", "[保持不变]"):
        if x not in txt:
            loi.append(f"thiếu {x}")
    # khung theo bo_khung
    bo = {str(x).upper() for x in (cl.get("bo_khung") or [])}
    gui = [k for k in KHUNG_KHOA if k not in bo]
    if gui:
        m = re.search(r"【关键帧】(.)张", txt)
        if not m:
            loi.append(f"thiếu mục 【关键帧】 (gửi {len(gui)} khung: {gui})")
        elif m.group(1) != so_zh(len(gui)):
            loi.append(f"【关键帧】 ghi {m.group(1)}张 nhưng gửi {len(gui)} khung {gui}")
    elif "【关键帧】" in txt or "画面参照" in txt:
        loi.append("cụm KHÔNG gửi khung nào nhưng còn 【关键帧】 / 画面参照")
    for k in KHUNG_KHOA:
        nh = NHAN_KHUNG_ZH[k]
        co_dong, co_moc = bool(re.search(rf"^- {nh}：", txt, re.M)), f"(画面参照{nh}" in txt
        if k in gui and not (co_dong and co_moc):
            loi.append(f"khung {nh} có gửi nhưng thiếu {'dòng mô tả' if not co_dong else 'móc (画面参照…)'}")
        if k not in gui and (co_dong or co_moc):
            loi.append(f"còn tả khung {nh} nhưng khung này KHÔNG gửi (bo_khung)")
    # nhân vật: ảnh 2 ô + nhận diện tối giản
    nv = sorted(tm[r]["ten"].upper() for r in refs if (tm.get(r) or {}).get("loai") == "nv")
    if nv:
        mau = MAU_NV_ZH.format(so_zh(len(nv)))
        if mau not in txt:
            loi.append(f"câu mở mục nhân vật phải đúng mẫu: {mau}")
        dong = re.findall(r"^- ([A-Z][A-Z ]*?)：(.*)$", txt, re.M)
        if sorted(d[0] for d in dong) != nv:
            loi.append(f"dòng nhân vật {sorted(d[0] for d in dong)} khác ảnh nhân vật sẽ gửi {nv}")
        for t, nd in dong:
            for w in NGHE_ZH:
                if w in nd:
                    loi.append(f"dòng nhận diện {t} có chữ nghề '{w}'")
            if not re.search(r"\(\d+岁\)", nd):
                loi.append(f"dòng nhận diện {t} thiếu (tuổi岁)")
            do = [w for w in DO if w in nd]
            if do:
                cb.append(f"dòng nhận diện {t} có chữ quần áo {do} — ảnh toàn thân đã có; chỉ giữ nếu cần tách hai người dễ lẫn")
            if len(nd) > 45:
                cb.append(f"dòng nhận diện {t} dài {len(nd)} ký tự — chỉ 1–2 đặc điểm")
    if re.search(r"半身|竖版|肖像", txt):
        cb.append("còn 半身/竖版/肖像 — ảnh nhân vật chuẩn là ảnh 2 ô, gọi là 人物图")
    # không ghi giờ
    for w in GIO_ZH:
        if w in txt:
            loi.append(f"còn chữ chỉ giờ '{w}'")
    for m in GIO_ZH_RE.finditer(txt):
        loi.append(f"còn giờ '{m.group(0)}'")
    for m in re.finditer(r".{0,6}(夜|阳光|日光|灯火|天色).{0,6}", txt):
        cb.append(f"xem lại '{m.group(0)}' — ánh sáng / thời điểm gắn giờ thì bỏ (ảnh bối cảnh tự quyết)")
    canh = re.search(r"^【场景图】.*$", txt, re.M)
    if canh:
        for w in ("灶台", "排烟罩", "锡箔", "炉灶", "锅"):
            if w in canh.group(0):
                cb.append(f"【场景图】 còn đồ bếp '{w}' — chỉ giữ mốc vị trí dòng thời gian dùng tới")
    # thoại — 02/10/2026 người dùng: viết {câu thoại} KHÔNG có ngoặc kép (cấu trúc thoại Seedance 2.5; luật {"…"} 29/09 đã bỏ)
    if re.search(r'\{\s*["“”]|["“”]\s*\}', txt):
        loi.append('thoại còn ngoặc kép — viết {câu thoại} không có "…" (luật 02/10/2026)')
    thoai = [fold(str(s.get("thoai") or "")) for s in cl["shots"] if str(s.get("thoai") or "").strip()]
    # 29/09 người dùng: câu thoại viết {"…"} (ngoặc nhọn + ngoặc kép) — bỏ ngoặc kép ở hai đầu rồi mới so nguyên văn
    trong = [fold(x.strip().strip('"“”')) for x in re.findall(r"\{([^{}]*)\}", txt)]
    if len(trong) != len(thoai):
        loi.append(f"có {len(trong)} câu {{…}}, kịch bản có {len(thoai)}")
    for t in thoai:
        if t not in trong:
            loi.append(f"câu thoại không khớp nguyên văn: {t!r}")
    if cu and trong != [fold(x.strip().strip('"“”')) for x in re.findall(r"\{([^{}]*)\}", cu)]:
        loi.append("câu thoại {…} khác bản cũ (--so-voi)")
    khoa = re.findall(r"除此之外没有任何人说话|全片没有任何人说话", txt)
    if len(khoa) != 1:
        loi.append(f"câu khoá thoại xuất hiện {len(khoa)} lần (phải đúng 1)")
    m = re.search(r"全片只有下面(.+?)句英语台词", txt)
    if thoai and (not m or m.group(1) != so_zh(len(thoai))):
        loi.append(f"câu khoá thoại phải ghi {so_zh(len(thoai))}句")
    im = sum(txt.count(w) for w in ("没有人说话", "一言不发", "不再说话", "都不说话"))
    if im > 1:
        cb.append(f"chữ gợi im lặng ('没有人说话'/'一言不发'/'不再说话') {im} lần — tối đa 1 lần, ở đoạn im lặng dài nhất "
                  "(dồn chữ im lặng làm clip câm, cụm 18/32)")
    for w in ("安静戏", "静默戏", "安静的戏", "无声戏"):
        if w in txt:
            cb.append(f"câu loại cảnh gọi '{w}' — gợi cả clip im lặng; tả cảm xúc thật của cảnh thay vào")
    # người có mặt mà không có thoại: phải được chặn nói (cụm 41: model bịa 13 câu tiếng Trung quanh GLORIA)
    noi = {str(s.get("noi") or "").upper() for s in cl["shots"] if str(s.get("thoai") or "").strip()}
    ten = re.findall(r"^- ([A-Z][A-Z ]*?)：", txt, re.M)
    chi_ai_noi = bool(re.search(r"只有[A-Z、和及 ]+(开口|各说|说话)", txt)) or "全片没有任何人说话" in txt   # đã nói rõ ai được nói
def main():
    ap = argparse.ArgumentParser(description="Kiểm prompt tiếng Trung viết tay (cách 2)")
    ap.add_argument("--project", required=True)
    ap.add_argument("cum", nargs="*", type=int)
    ap.add_argument("--so-voi", help="thư mục bản cũ (cum_NNN.txt) để kiểm thoại + câu chặn không bị rơi")
    a = ap.parse_args()
    duan = Path(a.project)
    b = json.loads((duan / "bible.json").read_text(encoding="utf-8"))
    cl = {c["n"]: c for c in b["clusters"]}
    refs = {c["n"]: c["refs"] for c in json.loads((duan / "du_an.json").read_text(encoding="utf-8"))["cum"]}
    tm = json.loads((duan / "anh" / "_ten_anh.json").read_text(encoding="utf-8"))
    tong = 0
    for n in (a.cum or sorted(cl)):
        f = duan / "_zh" / "prompt" / f"cum_{n:03d}.txt"
        if not f.exists():
            print(f"cụm {n}: THIẾU {f}")
            tong += 1
            continue
        cu_f = Path(a.so_voi) / f.name if a.so_voi else None
        cu = cu_f.read_text(encoding="utf-8").replace("\r\n", "\n") if cu_f and cu_f.exists() else ""
        txt = f.read_text(encoding="utf-8")
        ten_phim = {str(c.get("name", "")).upper() for c in b.get("characters", [])}
        tron = re.sub(r"（@图片\d+）", "", txt).replace("@", "")       # bài cổng 2: kiểm chuẩn đọc bài như bản không mã ảnh
        loi, cb = kiem(n, cl[n], refs.get(n, []), tm, tron, re.sub(r"（@图片\d+）", "", cu), ten_phim)
        loi += kiem_gan_het(txt, refs.get(n, []), tm, ten_phim)
        tong += len(loi)
        print(f"cụm {n}: {'OK' if not loi else f'{len(loi)} LỖI'}" + (f", {len(cb)} cảnh báo" if cb else ""))
        for x in loi:
            print("  LỖI  ", x)
        for x in cb:
            print("  C.BÁO", x)
    sys.exit(1 if tong else 0)
