            L.append(f"### Nơi `{bg}` — tên nơi: {v['noi']}")
            for p, cau in v["panels"].items():
                L.append(f"- {p}{'（@图片' + str(ma[p]) + '）' if p in ma else '  [KHÔNG GỬI]'}：{cau}")
